// src/components/layout/Layout.js
import React from 'react';
import Sidebar from './Sidebar';
import { Menu, X, Building2 } from 'lucide-react';

export default function Layout({ children }) {
  const [menuOpen, setMenuOpen] = React.useState(false);

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {/* Mobile Header */}
      <div className="mobile-only" style={{ 
        position: 'fixed', top: 0, left: 0, right: 0, height: 'var(--header-h)',
        background: 'var(--primary)', display: 'flex', alignItems: 'center', 
        justifyContent: 'space-between', padding: '0 20px', zIndex: 1000,
        boxShadow: 'var(--shadow-md)'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <Building2 size={24} color="#fff" />
          <span style={{ color: '#fff', fontWeight: 800, fontSize: 18, letterSpacing: '1px' }}>MLMS</span>
        </div>
        <button 
          onClick={() => setMenuOpen(!menuOpen)}
          style={{ background: 'transparent', border: 'none', color: '#fff', padding: 8 }}
        >
          {menuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      <Sidebar isOpen={menuOpen} onClose={() => setMenuOpen(false)} />

      {/* Overlay for mobile when sidebar is open */}
      {menuOpen && (
        <div 
          onClick={() => setMenuOpen(false)}
          style={{ 
            position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.4)', 
            backdropFilter: 'blur(4px)', zIndex: 900 
          }} 
          className="mobile-only"
        />
      )}

      <main className="main-content" style={{
        marginLeft: 'var(--sidebar-w)',
        flex: 1, padding: '28px 32px',
        minHeight: '100vh',
        marginTop: window.innerWidth < 1024 ? 'var(--header-h)' : 0
      }}>
        {children}
      </main>
    </div>
  );
}
